import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import "./AdminPage.css";

function AdminPage() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("dashboard");

  const [totalSlots, setTotalSlots] = useState(10); 
  const [bookings, setBookings] = useState([]);
  const [facilities, setFacilities] = useState([]);
  const [analytics, setAnalytics] = useState([]);
  const [users, setUsers] = useState([]);

  const [loadingBookings, setLoadingBookings] = useState(true);
  const [loadingFacilities, setLoadingFacilities] = useState(true);
  const [loadingAnalytics, setLoadingAnalytics] = useState(true);
  const [loadingUsers, setLoadingUsers] = useState(true);

  useEffect(() => {
    fetchBookings();
    fetchFacilities();
    fetchAnalytics();
    fetchUsers();
  }, []);

  const fetchBookings = async () => {
    try {
      const res = await fetch("http://localhost:8081/api/bookings");
      const data = await res.json();
      setBookings(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingBookings(false);
    }
  };

  const fetchFacilities = async () => {
    try {
      const res = await fetch("http://localhost:8081/facilities");
      const data = await res.json();
      setFacilities(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingFacilities(false);
    }
  };

  const fetchAnalytics = async () => {
    try {
      const res = await fetch("http://localhost:8081/facility-analytics");
      const data = await res.json();
      setAnalytics(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingAnalytics(false);
    }
  };

  const fetchUsers = async () => {
    setLoadingUsers(true);
    try {
      const res = await fetch("http://localhost:8081/api/users");
      const data = await res.json();
      setUsers(data.content || data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingUsers(false);
    }
  };

  const handleLogout = () => {
    localStorage.clear();
    navigate("/admin-login");
  };

  const renderContent = () => {
    if (activeTab === "dashboard") {
      const availableSlots = totalSlots - bookings.length;
      return (
        <div className="dashboard-content">
          <div className="stat-card">
            <h3>Total Slots</h3>
            <p>{totalSlots}</p>
          </div>
          <div className="stat-card">
            <h3>Available Slots</h3>
            <p>{availableSlots >= 0 ? availableSlots : 0}</p>
          </div>
          <div className="stat-card">
            <h3>Total Bookings</h3>
            <p>{loadingBookings ? "Loading..." : bookings.length}</p>
          </div>
          <div className="stat-card">
            <h3>Total Facilities</h3>
            <p>{loadingFacilities ? "Loading..." : facilities.length}</p>
          </div>
          <div className="stat-card">
            <h3>Total Users</h3>
            <p>{loadingUsers ? "Loading..." : users.length}</p>
          </div>
        </div>
      );
    }

    if (activeTab === "users") {
      if (loadingUsers) return <p>Loading users...</p>;
      if (!users.length) return <p>No registered users found.</p>;

      return (
        <div>
          <h2>Registered Users</h2>
          <table>
            <thead>
              <tr>
                <th>User ID</th>
                <th>Username</th>
                <th>Email</th>
                <th>Role</th>
              </tr>
            </thead>
            <tbody>
              {users.map((u) => (
                <tr key={u.id || u.userId}>
                  <td>{u.id || u.userId}</td>
                  <td>{u.username}</td>
                  <td>{u.email}</td>
                  <td>{u.role}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      );
    }

    if (activeTab === "bookings") return <p>Bookings content...</p>;
    if (activeTab === "facilities") return <p>Facilities content...</p>;
    if (activeTab === "analytics") return <p>Analytics content...</p>;
  };

  return (
    <div className="admin-dashboard">
      <div className="sidebar">
        <h2>Admin Panel</h2>
        <ul>
          <li onClick={() => setActiveTab("dashboard")}>Dashboard</li>
          <li onClick={() => setActiveTab("bookings")}>View Bookings</li>
          <li onClick={() => setActiveTab("facilities")}>Facilities</li>
          <li onClick={() => setActiveTab("analytics")}>Facility Analytics</li>
          <li onClick={() => setActiveTab("users")}>Signup Users</li>
        </ul>
      </div>

      <div className="main-content">
        <div className="topbar">
          <h1>{activeTab.charAt(0).toUpperCase() + activeTab.slice(1)}</h1>
          <button onClick={handleLogout}>Logout</button>
        </div>
        <div className="content-area">{renderContent()}</div>
      </div>
    </div>
  );
}

export default AdminPage;
